const app=document.querySelector('#app');
const cases=[
 {id:1,title:'行驶中异常断电反馈',topic:'车辆安全',source:'企微社群',level:'优先核验',vehicle:'示例车型 A',count:6,quote:'【虚构示例】今天骑行时突然断电，重新开机后恢复，想确认需要检查哪里。',reason:'描述了具体使用场景和异常现象，需要人工核验发生条件。不能仅凭文字认定故障原因。'},
 {id:2,title:'充电连接反复中断',topic:'充电体验',source:'抖音',level:'待核验',vehicle:'示例车型 B',count:12,quote:'【虚构示例】充电总是断断续续，换个插座还是一样。',reason:'独立评论，没有父帖或回复上下文。仅能识别充电异常表述，车型与原因无法从此评论确定。'},
 {id:3,title:'维修进度沟通不及时',topic:'售后服务',source:'小红书',level:'待核验',vehicle:'车型未识别',count:9,quote:'【虚构示例】送修几天了，问进度一直没有明确答复，希望能给个预计时间。',reason:'主要诉求为维修进度与沟通，不应直接升级为车辆安全事故。'},
 {id:4,title:'同类续航疑问重复出现',topic:'续航体验',source:'民间微信群',level:'持续观察',vehicle:'示例车型 C',count:18,quote:'【虚构示例】最近通勤感觉耗电快了，有没有相同使用情况的朋友？',reason:'需要结合气温、负载和骑行习惯核验。相似话题不等于同一故障或同一事件。'},
 {id:5,title:'固件升级后连接异常',topic:'软件体验',source:'快手',level:'待核验',vehicle:'车型未识别',count:4,quote:'【虚构示例】升级后手机连接经常断开，重新配对才恢复。',reason:'评论包含软件使用问题，但缺少版本与机型信息，先保留为待核验反馈。'}
];
const reviewed=new Set();let filter='全部来源',query='';
const chart=()=>`<svg class="chart" viewBox="0 0 650 210" role="img" aria-label="虚构趋势：社群与公域问题线索在八月中旬增多，月底回落"><g stroke="currentColor" opacity=".10"><path d="M30 35H630M30 90H630M30 145H630"/></g><path d="M30 143L70 129L110 139L150 114L190 120L230 95L270 117L310 83L350 38L390 69L430 56L470 91L510 79L550 102L590 108L630 90" fill="none" stroke="#36b9d6" stroke-width="3"/><path d="M30 164L70 148L110 154L150 137L190 150L230 126L270 135L310 110L350 86L390 105L430 95L470 132L510 114L550 143L590 133L630 140" fill="none" stroke="#a99af7" stroke-width="3"/><g><text x="30" y="196">08.01</text><text x="180" y="196">08.08</text><text x="330" y="196">08.15</text><text x="480" y="196">08.22</text><text x="590" y="196">08.31</text></g></svg>`;
const metrics=(dark=false)=>[['分析内容','8,640','虚构样本 · 非实际处理量'],['待核验事件',String(5-reviewed.size),'人工确认后进入处理'],['优先核验','01','安全相关表述'],['同类问题主题','12','不等同于已确认故障']].map(([l,n,note])=>`<div class="card"><div class="metric-label">${l}</div><div class="metric-number">${n}</div><div class="fine">${note}</div></div>`).join('');
function event(c){return `<button class="event" data-case="${c.id}"><span class="tag ${c.id===1?'risk':''}">${c.id===1?'优先':'观察'}</span><span class="event-content"><h3>${c.title}</h3><span class="fine">${c.source} · ${c.count} 条示例线索 · ${c.vehicle}</span></span><span class="chevron">›</span></button>`}
function command(){return `<section class="dark"><div class="topline"><div><div class="eyebrow">NINEBOT / LISTENING INTELLIGENCE</div><h1>每一条反馈，都值得被看见</h1><p class="muted" style="margin-top:10px;font-size:14px">舆情态势总览 · 8 月历史回放样品</p></div><div class="date">2026.08.01 — 08.31</div></div><div class="metrics">${metrics(true)}</div><div class="grid"><div><div class="card trend"><div class="section-head"><h2>问题线索趋势</h2><span class="tag">示意 · 非实测</span></div><div class="legend"><span><i></i>社群线索</span><span><i class="second"></i>公域线索</span></div>${chart()}<p class="fine">两类数据筛选口径不同，仅展示各自变化，不比较负面率。</p></div><div class="card"><div class="section-head"><h2>需要关注的事件</h2><a href="#b" class="fine">进入核验工作台 ›</a></div>${cases.slice(0,3).map(event).join('')}</div></div><div><div class="card"><div class="section-head"><h2>问题结构</h2><span class="fine">示例主题占比</span></div><div class="source-bars">${[['续航体验',34],['充电体验',26],['售后服务',22],['软件体验',12],['车辆安全',6]].map(([s,n])=>`<div class="bar-row"><span>${s}</span><div class="bar-track"><div class="bar-fill" style="width:${n*2}%"></div></div><span>${n}%</span></div>`).join('')}</div></div><div class="card" style="margin-top:24px"><div class="eyebrow">CROSS-CHANNEL SIGNAL</div><h2 style="line-height:1.6;margin-bottom:14px">充电异常，出现在不同渠道的讨论里</h2><p class="muted" style="font-size:14px">抖音评论与社群反馈呈现相似主题，建议合并核验问题类型，保留各自证据。</p><button class="outline" data-case="2" style="margin-top:22px">查看示例证据</button><p class="fine" style="margin-top:18px">相似反馈 ≠ 已证实跨渠道传播</p></div></div></div><p class="fine bottom-note">A / 适合现场投屏与风险总览。所有数字、事件和趋势均为设计示例，未调用模型或发送预警。</p></section>`}
function work(){return `<section class="workspace"><aside class="sidebar"><div class="wordmark">ninebot<span style="color:#3262dc">.</span></div><p class="fine">舆情与用户声音</p><a class="side-item chosen" href="#b">▤　风险核验</a><a class="side-item" href="#a">◫　态势总览</a><a class="side-item" href="#c">◷　月度洞察</a><a class="side-item" href="#compare">⊞　方案对照</a><div class="side-note">历史演示模式<br>不连接真实数据<br>操作仅在当前页面有效</div></aside><div class="work-main"><div class="section-head"><div><div class="eyebrow muted" style="margin-bottom:12px">WORKSPACE / REVIEW</div><h1>风险核验</h1><p class="muted" style="font-size:14px;margin-top:10px">从待办出发，查看证据，再做判断。</p></div><span class="tag">2026 年 8 月 · 示例</span></div><div class="metrics">${metrics()}</div><div class="card queue"><div class="section-head"><h2>事件队列 <span class="muted" style="font-size:14px">/ 5 条示例</span></h2><button id="reset">重置演示操作</button></div><div class="toolbar"><input id="search" aria-label="搜索事件" placeholder="搜索问题、车型或关键词"><select id="source" aria-label="来源筛选"><option>全部来源</option>${[...new Set(cases.map(c=>c.source))].map(x=>`<option>${x}</option>`).join('')}</select></div><div id="queue-results"></div><div class="demo-banner">独立评论只依据自身文字分析。缺少上下文时保留不确定性，不自动补齐故障原因。</div></div><p class="fine" style="margin-top:20px">B / 适合日常处理与闭环演示。搜索、来源筛选和示例确认可操作；不触发真实通知。</p></div></section>`}
function report(){return `<article class="report"><header class="masthead"><span>NINEBOT / 用户声音观察</span><span>2026 · AUGUST / 设计示例</span></header><section class="hero"><div><span class="chip">月度洞察 · 虚构内容</span><h1>听见反馈，<br>看见问题背后的需求。</h1><p>从一条评论，到一个值得关注的共性问题。以证据组织发现，以用户体验解释业务价值。</p></div><div class="hero-aside"><div class="eyebrow">MONTHLY FOCUS</div><div class="hero-number">03</div><p>个值得展开的观察方向</p><div class="fine">充电体验 / 售后沟通 / 软件连接<br>以下结论仅为版式示例，并非真实月报。</div></div></section><section class="findings"><div class="finding"><span class="num">01</span><h2>问题不仅是“充不上电”</h2><p>示例反馈集中在反复中断、恢复步骤与原因不明，提示我们关注故障描述之外的使用困惑。</p><button data-case="2">查看评论证据 ›</button></div><div class="finding"><span class="num">02</span><h2>等待，也是一种体验</h2><p>示例用户希望获得明确的维修进度与预计时间，诉求不一定是更快维修，也可能是及时解释。</p><button data-case="3">查看售后案例 ›</button></div><div class="finding"><span class="num">03</span><h2>小障碍，反复被提起</h2><p>示例中的连接与配对问题不一定有高风险，但值得在体验优化清单中持续跟踪。</p><button data-case="5">查看软件反馈 ›</button></div></section><section class="feature"><div class="feature-copy"><div class="eyebrow">FROM SIGNAL TO ACTION</div><h2>同一问题，<br>不同渠道的表达。</h2><p style="font-size:14px">公域评论呈现简短诉求，社群讨论可以补充使用场景。把相似问题放在一起看，同时保留证据边界。</p><button data-case="2">展开事件核验示例</button></div><div class="feature-chart"><div class="legend"><span><i></i>社群线索</span><span><i class="second"></i>公域线索</span></div>${chart()}<p class="fine">趋势仅为视觉示意，不代表真实数量或传播链路。</p></div></section><footer class="report-footer"><span>C / 面向比赛评委与业务管理者<br>先呈现发现，再展开证据和行动。</span><span>数据边界：历史回放 · 独立评论无上下文<br>本页所有案例与数字均为虚构。</span></footer></article>`}
function compare(){return `<section class="compare"><div class="eyebrow muted" style="margin-bottom:16px">DESIGN REVIEW / 01</div><h1>选的不只是颜色，还有看问题的方式。</h1><p>三套样品使用同一组虚构案例。先分别体验，再挑选适合你的页面组合。</p><div class="comparison-grid"><div class="option"><div class="mini a"><span></span><span></span><span></span><span></span></div><div class="option-body"><h2>A · 指挥中心</h2><p>深海蓝 / 高对比 / 数据密集<br><br>先看总体态势 → 发现异常 → 进入事件。<br>适合比赛投屏、快速巡检。</p><a href="#a">体验方案 A</a></div></div><div class="option"><div class="mini b"><span></span><span></span></div><div class="option-body"><h2>B · 业务工作台</h2><p>冷白 / 克制蓝 / 清晰表格<br><br>先看待办 → 筛选定位 → 核验证据。<br>适合日常操作、展示处理闭环。</p><a href="#b">体验方案 B</a></div></div><div class="option"><div class="mini c">User voices.<br>Business insights.</div><div class="option-body"><h2>C · 月度观察</h2><p>纸白 / 墨绿 / 编辑式排版<br><br>先看结论 → 解释影响 → 展开证据。<br>适合评委阅读、管理层汇报。</p><a href="#c">体验方案 C</a></div></div></div><div class="decision"><h2>可以混搭，不必三选一</h2><p>推荐组合：<strong>C 作为展示首页，B 作为核验后台，A 用于现场投屏。</strong></p><p>和同事讨论时，可以直接描述：“保留 C 的信息顺序，换成 B 的配色；详情页用 B，趋势图用 A。”</p><p class="fine">本轮只评审视觉和信息组织，不验证真实模型效果。页面内操作不保存到服务器，刷新后恢复初始状态。</p></div></section>`}
function table(){const a=cases.filter(c=>(filter==='全部来源'||c.source===filter)&&[c.title,c.vehicle,c.topic].some(x=>x.includes(query)));document.querySelector('#queue-results').innerHTML=a.length?`<div class="table-wrap"><table><thead><tr><th>事件 / 车型</th><th>来源</th><th>核验状态</th><th>示例线索</th><th>操作</th></tr></thead><tbody>${a.map(c=>`<tr><td>${c.title}<small>${c.vehicle} · ${c.topic}</small></td><td>${c.source}</td><td><span class="tag ${c.id===1&&!reviewed.has(c.id)?'risk':''}">${reviewed.has(c.id)?'已确认（模拟）':c.level}</span></td><td>${c.count} 条</td><td><button class="text-button" data-case="${c.id}">查看证据</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">没有匹配的示例事件，请调整关键词或来源。</div>'}
function render(){const view=location.hash.slice(1)||'a';document.querySelectorAll('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});app.innerHTML=view==='b'?work():view==='c'?report():view==='compare'?compare():command();if(view==='b'){query='';filter='全部来源';table();document.querySelector('#search').addEventListener('input',e=>{query=e.target.value.trim();table()});document.querySelector('#source').addEventListener('change',e=>{filter=e.target.value;table()});document.querySelector('#reset').onclick=()=>{reviewed.clear();render()}}window.scrollTo(0,0)}
function detail(id){const c=cases.find(c=>c.id===id);const isComment=[2,5].includes(id);document.querySelector('#detail-body').innerHTML=`<div class="detail-kicker">示例事件 / DEMO-${String(id).padStart(3,'0')}</div><h2>${c.title}</h2><div class="detail-meta"><span class="tag">${c.source}</span><span class="tag">${c.topic}</span><span class="tag ${id===1?'risk':''}">${c.level}</span></div><h3>原文证据 · 虚构</h3><blockquote>${c.quote}</blockquote><p class="fine">${isComment?'独立评论 · 上下文不可获取 · 不从其他评论拼造对话':'社群或主帖示例 · 真实系统需保留来源引用'}<br>本样品不包含真实账号、群名或原文链接。</p><h3>分析解释 · 示例</h3><p>${c.reason}</p><h3>建议核验</h3><p>确认描述是否完整、是否为亲历反馈，并核对时间、车型与问题细节。模型提示仅作为线索，不代表已确认事实。</p><div class="dialog-actions"><button class="primary" id="confirm-demo">${reviewed.has(id)?'已确认（模拟）':'模拟确认并加入预警队列'}</button><button id="return-demo">返回查看</button></div><div id="confirm-note" role="status">${reviewed.has(id)?'<div class="notice">此示例已确认。没有发送真实通知。</div>':''}</div>`;document.querySelector('#confirm-demo').onclick=()=>{reviewed.add(id);document.querySelector('#confirm-demo').textContent='已确认（模拟）';document.querySelector('#confirm-note').innerHTML='<div class="notice">已加入当前页面的模拟预警队列。未发送飞书通知，刷新后恢复初始状态。</div>';if(location.hash==='#b'){table();document.querySelector('.work-main .metrics').innerHTML=metrics()}};document.querySelector('#return-demo').onclick=()=>document.querySelector('#detail').close();document.querySelector('#detail').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-case]');if(b)detail(Number(b.dataset.case))});document.querySelector('.close').onclick=()=>document.querySelector('#detail').close();window.addEventListener('hashchange',render);render();
